function extractCoursesFromHTML(html) {
  if (!html || typeof html !== 'string') return [];
  const text = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ').trim();
  const patterns = [
    /B\.?\s?Tech[^\n,<]{0,40}/gi, /M\.?\s?Tech[^\n,<]{0,40}/gi,
    /MBBS[^\n,<]{0,30}/gi,        /BDS[^\n,<]{0,30}/gi,
    /MBA[^\n,<]{0,40}/gi,         /PGDM[^\n,<]{0,40}/gi,
    /BCA[^\n,<]{0,30}/gi,         /MCA[^\n,<]{0,30}/gi,
    /BBA[^\n,<]{0,30}/gi,         /B\.?\s?Sc[^\n,<]{0,40}/gi,
    /B\.?\s?Com[^\n,<]{0,30}/gi,  /LLB[^\n,<]{0,30}/gi,
    /B\.?\s?Arch[^\n,<]{0,30}/gi, /B\.?\s?Pharm[^\n,<]{0,30}/gi,
    /\bCA\b[^\n,<]{0,30}/g,
    /Diploma in [A-Z][a-zA-Z\s]{3,40}/g,
    /Bachelor of [A-Z][a-zA-Z\s]{3,50}/g,
    /Master of [A-Z][a-zA-Z\s]{3,50}/g,
  ];
  const found = new Set();
  patterns.forEach(p => {
    (text.match(p) || []).slice(0, 5).forEach(m => {
      const clean = m.trim().replace(/[|•·–—]/g, '').trim();
      if (clean.length > 2 && clean.length < 80) found.add(clean);
    });
  });
  return [...found];
}


