}

function tagsToText(fragment) {
  return fragment
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ').trim();
}

function extractArticleText(html) {
  const noHead = html.replace(/<head[\s\S]*?<\/head>/i, '');
  const cleaned = stripBoilerplateTags(noHead);

  const CONTENT_PATTERNS = [
    /<article[^>]*>([\s\S]*?)<\/article>/i,
    /<main[^>]*>([\s\S]*?)<\/main>/i,
    /<div[^>]*class="[^"]*(?:articleBody|story-body|post-content|entry-content|article-content|article-body|content-body)[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /<div[^>]*(?:role|itemprop)="(?:main|articleBody)"[^>]*>([\s\S]*?)<\/div>/i
  ];

  for (const pattern of CONTENT_PATTERNS) {
    const m = cleaned.match(pattern);
    if (m && m[1]) {
      const text = tagsToText(m[1]);
      if (text.length > 200) return text;
    }
  }

  const bodyMatch = cleaned.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  const scope = bodyMatch && bodyMatch[1] ? bodyMatch[1] : cleaned;
  return tagsToText(scope);
}

