    .replace(/<header[\s\S]*?<\/header>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<aside[\s\S]*?<\/aside>/gi, '')
    .replace(/<form[\s\S]*?<\/form>/gi, '')
    .replace(/<svg[\s\S]*?<\/svg>/gi, '')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
    .replace(/<iframe[\s\S]*?<\/iframe>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '');
}

function tagsToText(fragment) {
  return fragment
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ').trim();
}

function extractArticleText(html) {
  const noHead = html.replace(/<head[\s\S]*?<\/head>/i, '');
  const cleaned = stripBoilerplateTags(noHead);

  const CONTENT_PATTERNS = [
    /<article[^>]*>([\s\S]*?)<\/article>/i,
    /<main[^>]*>([\s\S]*?)<\/main>/i,
    /<div[^>]*class="[^"]*(?:articleBody|story-body|post-content|entry-content|article-content|article-body|content-body)[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /<div[^>]*(?:role|itemprop)="(?:main|articleBody)"[^>]*>([\s\S]*?)<\/div>/i
  ];

  for (const pattern of CONTENT_PATTERNS) {
    const m = cleaned.match(pattern);
    if (m && m[1]) {
      const text = tagsToText(m[1]);
      if (text.length > 200) return text;
    }
  }

  const bodyMatch = cleaned.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  const scope = bodyMatch && bodyMatch[1] ? bodyMatch[1] : cleaned;
  return tagsToText(scope);
}

try {
  const raw = $json.data || $json.body || $json;
  const html = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const isFetchError = !html || html.length < 50 || $json.error;
  let link = '', title = '', source_name = '';
  try {
    const src = $('Pick Top 3 Google Search Results').item.json;
    link = src.link || ''; title = src.title || ''; source_name = src.source_name || '';
  } catch (e2) {}
  if (isFetchError) {
    return { json: { link: link, title: title, source_name: source_name, article_text: '', fetch_failed: true } };
  }
  const text = extractArticleText(html);
  return { json: { link: link, title: title, source_name: source_name, article_text: text.slice(0, 9000), fetch_failed: false } };
} catch (outerErr) {
  return { json: { link: '', title: '', source_name: '', article_text: '', fetch_failed: true, strip_error: String(outerErr && outerErr.message || outerErr) } };
}

const items = $input.all().map(function(i) { return i.json; }).filter(function(it) { return !it.fetch_failed && it.article_text; });
if (!items.length) {
