}
const blocks = items.map(function(it, idx) {
  return 'RESULT ' + (idx + 1) + ' (source: ' + (it.source_name || 'unknown') + ', title: "' + it.title + '"):\n' + it.article_text;
});
return [{ json: { prompt_text: blocks.join('\n\n---\n\n'), article_count: items.length } }];

const HEADLINE_PATTERNS = [
  /\blakh\b/i, /\bcrore\b/i, /\bresult(s)?\b/i, /\btoday\b/i, /\byesterday\b/i,
  /\bapply now\b/i, /\badmission[s]?\s+open/i, /\bregistration/i, /\bnotification/i,
  /\bexam\s+date/i, /\bscore\s?card/i, /\bmerit\s+list/i, /\bcut\s?off/i,
  /[;?!]/, /\bwhat\s+after\b/i, /\bhow\s+to\b/i, /\bnews\b/i,
  /\d{4}-\d{2}-\d{2}/, /\bdeclared\b/i, /\breleased\b/i
];
function looksLikeHeadline(name) { return HEADLINE_PATTERNS.some(function(p) { return p.test(name); }); }

function extractArrayText(resp) {
  try {
    const candidate = (resp.candidates && resp.candidates[0]) || null;
    if (!candidate) return '';
    const parts = (candidate.content && candidate.content.parts) || [];
    const texts = parts.map(function(p) { return p.text || ''; }).filter(Boolean);
    return texts.join('\n');
  } catch (e) { return ''; }
}

let items = [];
try {
  const resp = $input.first().json;
  const text = extractArrayText(resp);
  const fb = text.indexOf('[');
  const lb = text.lastIndexOf(']');
  const jsonSlice = (fb !== -1 && lb !== -1 && lb > fb) ? text.slice(fb, lb + 1) : '[]';
  const names = JSON.parse(jsonSlice);
  const seen = new Set();
  (Array.isArray(names) ? names : []).forEach(function(raw) {
    if (!raw) return;
    const name = String(raw).trim();
    if (name.length < 2 || name.length > 100) return;
    if (looksLikeHeadline(name)) return;
    const norm = name.toLowerCase();
    if (seen.has(norm)) return;
    seen.add(norm);
    items.push({
      course_name: name,
      normalized_name: norm,
      source_type: 'google_search',
      search_volume: 0,
      popularity_score: 1,
      hiring_demand: 0,
      mentions: 1,
      discussion_count: 0,
      growth_pct: 0,
      raw: { method: 'ai_article_extract' }
    });
  });
} catch (e) {
  items = [];
}

if (items.length === 0) {
  return [{ json: { source_type: 'google_search', empty: true } }];
}
return [{ json: { source_type: 'google_search', item_count: items.length, items: items } }];
